-- Pre-A1 Media Phase, Part 1: human-pronunciation audio Material rows.
-- Every row here was individually verified via the Wikimedia Commons
-- API before being written (title exists, real sourceUrl resolves,
-- real license/artist metadata read from the file's own description
-- page) -- see the session's verification log. All are drawn from
-- Wiktionary's "En-us-word.ogg" pronunciation project: real people
-- (chiefly the Commons contributor "Dvortygirl", using the Shtooka
-- recording tool, explicitly for language-reference purposes) reading
-- the word aloud and self-publishing the recording as "Own work" --
-- genuinely human, never AI-generated, hence isHumanVoice: true.
--
-- 5 vocabulary items ("please repeat", "please speak slowly",
-- "I don't understand", "please help me", "years old") have NO
-- matching row here -- no real single-file recording of those exact
-- phrases could be found. They stay without audio_material_id,
-- honestly pending, rather than mismatching single-word audio to a
-- multi-word headword or fabricating a source.

WITH academy AS (SELECT id FROM "academy"."academies" LIMIT 1)
INSERT INTO "curriculum"."content_items" ("academy_id", "type", "cefr_level", "status", "payload")
SELECT academy.id, 'material'::"shared"."content_type", 'pre_a1'::"shared"."cefr_level", 'published'::"shared"."content_status", v.payload::jsonb
FROM academy, (VALUES
